import re
from typing import Dict, Any

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    sections: Dict[str, Dict[str, str]] = {}
    current_section = None
    current_key = None
    current_value = []
    default_values = {}
    lines = text.splitlines()

    # Regex patterns
    section_pattern = re.compile(r'^\s*\[([^\]]+)\]\s*$')
    key_value_pattern = re.compile(r'^(\S+)\s*(=|:)\s*(.*)$')
    comment_pattern = re.compile(r'^\s*(?:;|#).+$')
    inline_comment_pattern = re.compile(r'^\s*(.*?)\s*(?:;|#)\s*(.*)$')
    continuation_pattern = re.compile(r'^\s+(.*)$')
    quoted_value_pattern = re.compile(r'^"(.*)"$')

    for line in lines:
        stripped = line.strip()
        if not stripped or comment_pattern.match(line):
            continue

        # Check for section
        section_match = section_pattern.match(line)
        if section_match:
            current_section = section_match.group(1)
            if current_section not in sections:
                sections[current_section] = {}
            current_key = None
            current_value = []
            continue

        # Check for key-value pair
        if current_key is None:
            if not current_section:
                raise ValueError("Key line before any section header")

            kv_match = key_value_pattern.match(line)
            if not kv_match:
                raise ValueError(f"Malformed line: {line}")

            key, sep, value = kv_match.group(1), kv_match.group(2), kv_match.group(3)
            current_key = key.lower()
            current_value = []

            # Handle inline comments
            inline_match = inline_comment_pattern.match(line)
            if inline_match:
                value = inline_match.group(1)
                inline_comment = inline_match.group(2)
                if inline_comment.strip():
                    value = value.strip()

            # Check for quoted value
            if value.startswith('"') and value.endswith('"'):
                value = value[1:-1]
                current_value.append(value)
            else:
                # Split on first = or :
                value = value.split(sep, 1)[0].strip()
                current_value.append(value)
            continue

        # Handle continuation line
        if continuation_pattern.match(line):
            continuation = line.strip()
            if continuation.startswith('"') and continuation.endswith('"'):
                continuation = continuation[1:-1]
                current_value.append(continuation)
            else:
                current_value.append(continuation)
            continue

        # Handle value assignment (not continuation)
        if current_key is not None:
            value = line
            if value.startswith('"') and value.endswith('"'):
                value = value[1:-1]
                current_value.append(value)
            else:
                # Split on first = or :
                sep_pos = min(value.find('='), value.find(':'))
                if sep_pos != -1:
                    value = value[:sep_pos].strip()
                current_value.append(value)

            # Join all parts of the value
            joined_value = '\n'.join(current_value).strip()
            if current_section:
                sections[current_section][current_key] = joined_value
            else:
                default_values[current_key] = joined_value
            current_key = None
            current_value = []

    # Process DEFAULT section
    if 'DEFAULT' in sections:
        default_values.update(sections.pop('DEFAULT'))

    # Merge DEFAULT values into all sections
    for section in sections:
        for key in default_values:
            if key not in sections[section]:
                sections[section][key] = default_values[key]

    # Resolve interpolations
    def resolve_interpolation(value: str, section: str, current_section: str) -> str:
        def replace_match(match):
            ref = match.group(1)
            if ':' in ref:
                target_section, key = ref.split(':', 1)
                if target_section not in sections:
                    raise KeyError(f"Section '{target_section}' not found")
                target_value = sections[target_section].get(key)
                if target_value is None:
                    raise KeyError(f"Key '{key}' not found in section '{target_section}'")
                return resolve_interpolation(target_value, target_section, current_section)
            else:
                key = ref
                # Check current section first
                if key in sections[current_section]:
                    current_value = sections[current_section][key]
                else:
                    # Check DEFAULT
                    if key in default_values:
                        current_value = default_values[key]
                    else:
                        raise KeyError(f"Key '{key}' not found in section '{current_section}' or DEFAULT")
                return resolve_interpolation(current_value, current_section, current_section)

        interpolate_pattern = re.compile(r'\$\{([^}]+)\}')
        try:
            return interpolate_pattern.sub(replace_match, value)
        except RecursionError:
            raise ValueError("Interpolation cycle detected")

    # Apply interpolation to all values
    for section in sections:
        for key in sections[section]:
            sections[section][key] = resolve_interpolation(sections[section][key], section, section)

    return sections
