def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    nums = sorted(set(nums))
    result = []
    i = 0
    n = len(nums)

    while i < n:
        start = nums[i]
        j = i + 1
        while j < n and nums[j] == nums[j - 1] + 1:
            j += 1

        if j - i >= 3:
            result.append(f"{start}..{nums[j - 1]}")
        else:
            for k in range(i, j):
                result.append(str(nums[k]))

        i = j

    return ",".join(result)
